item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic a,
    input  logic b,
    input  logic c,
    output wire  w,
    output wire  x,
    output wire  y,
    output wire  z
);
    assign w = a;
    assign x = b;
    assign y = b;
    assign z = c;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic a, b, c;
    wire w, x, y, z;
    integer i, j, k;
    integer checks = 0;
    TopModule dut (.a(a), .b(b), .c(c), .w(w), .x(x), .y(y), .z(z));

    function automatic logic value(input integer index);
        case (index)
            0: value = 1'"'b0;
            1: value = 1'b1;
            2: value = 1'bx;
            3: value = 1'bz;
        endcase
    endfunction

    task automatic check_connections;
        #1;
        if (w "'!== a || x !== b || y !== b || z !== c)
            $fatal(1, "FAIL: inputs=%b%b%b outputs=%b%b%b%b", a,b,c,w,x,y,z);
        checks = checks + 1;
    endtask

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            {a,b,c} = i[2:0];
            check_connections();
        end
        for (i = 0; i < 4; i = i + 1)
            for (j = 0; j < 4; j = j + 1)
                for (k = 0; k < 4; k = k + 1) begin
                    a = value(i);
                    b = value(j);
                    c = value(k);
                    check_connections();
                end
        $display("PASS: %0d connection checks", checks);
        $finish;
    end

    initial begin
        #1000;
        $fatal(1, "FAIL: watchdog timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > development_compile.log 2>&1
compile_status=$?
print -r -- "$compile_status" > development_compile.exit
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > development_simulation.log 2>&1
    print -r -- "$?" > development_simulation.exit
fi
cat development_compile.log development_simulation.log'

